    if (nums.length == 1) {
        List<Integer> list = new ArrayList<>();
        list.add(nums[0]);
        result.add(list);
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> subList = new ArrayList<>();
        subList.add(num);
        for (int j = 0; j < nums.length; j++) {
            if (j != i) {
                subList.add(nums[j]);
            }
        }
        List<List<Integer>> subResult = permute(subList.toArray());
        for (List<Integer> subPermutation : subResult) {
            subPermutation.add(0, num);
            result.add(subPermutation);
        }
    }
    return result;
}
