public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring length to 0
    int largestSubstringLength = 0;

    // Iterate over each string in the input list
    for (String string : strings) {
        // Get the length of the current string
        int stringLength = string.length();

        // Check if the current string is longer than the largest substring length
        if (stringLength > largestSubstringLength) {
            // If the current string is longer, set the largest substring length to its length
            largestSubstringLength = stringLength;
        }

        // Iterate over each character in the current string
        for (int i = 0; i < stringLength; i++) {
            // Get the current character
            char currentChar = string.charAt(i);

            // Check if the current character is a letter
            if (Character.isLetter(currentChar)) {
                // Get the index of the current character in the current string
                int currentCharIndex = string.indexOf(currentChar);

                // Check if the current character is the last character in the current string
                if (currentCharIndex == stringLength - 1) {
                    // If the current character is the last character, check if its inverse can be found as a substring of any of the given strings
                    for (String otherString : strings) {
                        // Check if the inverse of the current character can be found in the other string
                        if (otherString.contains(Character.toLowerCase(currentChar))) {
                            // If the inverse of the current character can be found, set the largest substring length to the length of the current string
                            largestSubstringLength = stringLength;
                            break;
                        }
                    }
                }
            }
        }
    }

    // Return the largest substring length
    return largestSubstringLength;
}
