    Arrays.sort(arr);

    // Calculate the smallest 5% and largest 5% of the elements
    int smallest5Percent = (int) (arr.length * 0.05);
    int largest5Percent = (int) (arr.length * 0.95);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = smallest5Percent; i < arr.length - largest5Percent; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    double mean = (double) sum / (arr.length - 2 * (smallest5Percent + largest5Percent));

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
