public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(
                uglyNumbers[i2] * 2,
                Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == uglyNumbers[i2] * 2) {
            i2++;
        }
        if (nextUglyNumber == uglyNumbers[i3] * 3) {
            i3++;
        }
        if (nextUglyNumber == uglyNumbers[i5] * 5) {
            i5++;
        }
    }

    return uglyNumbers[n - 1];
}
